import sys
import os
import shutil
import importlib
from .plugin import Plugin
from .plugin_event import PluginEvent
import log

dir = "./plugins/"
class _PluginManager:
    def __init__(self) -> None:
        sys.path.insert(0,dir)
        self.plugins: list[Plugin] = []

    def load(self):
        for folder in os.listdir(dir):
            if not os.path.isdir(dir+folder): continue
            if folder == "__pycache__": continue
            plugin_module = importlib.import_module(folder)
            self.plugins.append(plugin_module.Main())

    def load_all(self):
        for p in self.plugins:
            log.info("> %s"%p.represent())
            p.load()

    def initialize_all(self):
        for p in self.plugins:
            p.initialize()

    def unload_all(self):
        for p in self.plugins:
            p.unload()

    def reload_all(self):
        PluginEvent.__check_empty__()
        for p in self.plugins:
            p.unload()
            p.load()

PluginManager = _PluginManager()